export function findAccurateStateData(nameOrAlias: string): AccurateStateMapData | undefined {
  if (!nameOrAlias) return undefined;
  const norm = nameOrAlias.trim().toLowerCase();
  return ACCURATE_INDIA_STATES_DATA.find(
    s => s.name.toLowerCase() === norm ||
         s.rawName.toLowerCase() === norm ||
         s.id.toLowerCase() === norm ||
         norm.includes(s.name.toLowerCase()) ||
         s.name.toLowerCase().includes(norm)
  );
}

export function findZoomedStateData(nameOrAlias: string): ZoomedStateMapData | undefined {
  if (!nameOrAlias) return undefined;
  const norm = nameOrAlias.trim().toLowerCase();
  const key = Object.keys(ACCURATE_STATE_ZOOM_DATA).find(
    k => k.toLowerCase() === norm ||
         norm.includes(k.toLowerCase()) ||
         k.toLowerCase().includes(norm)
  );
  return key ? ACCURATE_STATE_ZOOM_DATA[key] : undefined;
}
